#!/usr/bin/env bash
# Self-test for attribution-guard.sh: builds a throwaway repo with git commit-tree (no hooks run, nothing is
# committed to this repository) and checks that every marker fails the guard and clean text passes.
# Usage: attribution-guard-selftest.sh   (run from anywhere; needs git and bash)
set -u -o pipefail
GUARD="$(cd "$(dirname "$0")" && pwd)/attribution-guard.sh"
[ -f "$GUARD" ] || { echo "guard script not found: $GUARD"; exit 2; }
W=$(mktemp -d) || exit 2
trap 'rm -rf "$W"' EXIT
cd "$W" && git init -q . || exit 2

JN='Jordan Allen Lewis'; JE='42820601+jordanallenlewis@users.noreply.github.com'
TREE=$(git hash-object -t tree -w /dev/null)
# marker strings are assembled from parts so this file itself carries none of them
CS="Claude-""Session"; AG="Ag""ent"; CO="Co-authored""-by"; CC="Claude"" Code"

mk() { # message parent [author-name author-email committer-name committer-email] -> sha
  local m=$1 p=$2 an=${3:-$JN} ae=${4:-$JE} cn=${5:-$JN} ce=${6:-$JE}
  GIT_AUTHOR_NAME=$an GIT_AUTHOR_EMAIL=$ae GIT_COMMITTER_NAME=$cn GIT_COMMITTER_EMAIL=$ce \
    git commit-tree "$TREE" -p "$p" -m "$m"
}
ROOT=$(GIT_AUTHOR_NAME=$JN GIT_AUTHOR_EMAIL=$JE GIT_COMMITTER_NAME=$JN GIT_COMMITTER_EMAIL=$JE git commit-tree "$TREE" -m "root") || exit 2
BASE=$(mk "base" "$ROOT")

pass=0; failn=0
run() { # name expected-exit-class(0|nonzero) event base head [title body author headref]
  local name=$1 want=$2 ev=$3 base=$4 head=$5 title=${6:-} body=${7:-} author=${8:-jordanallenlewis} hr=${9:-feature}
  EVENT=$ev BASE=$base HEAD=$head TITLE=$title BODY=$body PR_AUTHOR=$author HEAD_REF=$hr bash "$GUARD" >"$W/out.txt" 2>&1
  local rc=$?
  if { [ "$want" = 0 ] && [ "$rc" = 0 ]; } || { [ "$want" = nonzero ] && [ "$rc" != 0 ]; }; then
    echo "ok   $name (exit $rc)"; pass=$((pass+1))
  else
    echo "FAIL $name (exit $rc, wanted $want)"; sed 's/^/     | /' "$W/out.txt"; failn=$((failn+1))
  fi
}
pr() { run "$1" "$2" pull_request "$BASE" "$3" "${4:-}" "${5:-}" "${6:-jordanallenlewis}" "${7:-feature}"; }
msgcase() { local h; h=$(mk "$2" "$BASE"); pr "$1" "$3" "$h"; }

echo "== must pass =="
msgcase "clean commit" "Fix the retry loop" 0
msgcase "product mention: grades servers for Claude clients" "Grade servers for Claude clients and for $CC users" 0
pr "clean title and body, product mention" 0 "$(mk "Docs" "$BASE")" "Works with $CC" "Grades servers for Claude clients"
H=$(mk "Squash merge" "$BASE" "$JN" "$JE" "GitHub" "noreply@github.com"); pr "GitHub web-merge committer" 0 "$H"
H=$(mk "Bump x" "$BASE" "dependabot[bot]" "49699333+dependabot[bot]@users.noreply.github.com" "GitHub" "noreply@github.com")
pr "dependabot PR keeps its bot identity" 0 "$H" "Bump x" "" "dependabot[bot]" "dependabot/npm/x"
H=$(mk "Fleet commit" "$BASE" "Jordan Lewis" "$JE" "Jordan Lewis" "$JE"); run "push: fleet bot name Jordan Lewis, Jordan email" 0 push "$BASE" "$H"
H=$(mk "Direct push, clean" "$BASE"); run "push: clean commit" 0 push "$BASE" "$H"
run "push: zero before sha (new branch), clean head" 0 push 0000000000000000000000000000000000000000 "$H"

echo "== markers that blocked before this change =="
msgcase "$CS trailer" "x"$'\n\n'"$CS: abc" nonzero
msgcase "claude.ai/code link" "x"$'\n\n'"https://claude.ai/code/session_1" nonzero
msgcase "claude.com/claude-code link" "x"$'\n\n'"see https://claude.com/claude-code" nonzero
msgcase "$AG trailer" "x"$'\n\n'"$AG: Hannah" nonzero
msgcase "indented $AG trailer" "x"$'\n\n'"   $AG: Hannah" nonzero
msgcase "$CO trailer (Jordan's own)" "x"$'\n\n'"$CO: Jordan Allen Lewis <$JE>" nonzero
msgcase "Generated with [$CC]" "x"$'\n\n'"Generated with [$CC](https://claude.com/claude-code)" nonzero
msgcase "Requested-by trailer" "x"$'\n\n'"Requested-by: Maya" nonzero
pr "title: $AG trailer line" nonzero "$(mk "ok" "$BASE")" "$CS: x"
pr "body: claude.ai/code link" nonzero "$(mk "ok" "$BASE")" "ok" "made at https://claude.ai/code/x"
pr "agent email author" nonzero "$(mk "ok" "$BASE" "$JN" "hq-sealmark@agent.local")"

echo "== markers added in this change =="
msgcase "lone robot emoji" "Fix thing "$'\xf0\x9f\xa4\x96' nonzero
msgcase "Generated by Claude" "x"$'\n\n'"Generated by Claude" nonzero
msgcase "Signed-off-by: Claude" "x"$'\n\n'"Signed-off-by: Claude <noreply@x.test>" nonzero
pr "title: robot emoji" nonzero "$(mk "ok" "$BASE")" $'\xf0\x9f\xa4\x96 add thing'
pr "body: Generated by Claude" nonzero "$(mk "ok" "$BASE")" "ok" "Generated by Claude"
pr "author NAME is Claude, email Jordan's" nonzero "$(mk "ok" "$BASE" "Claude" "$JE" "$JN" "$JE")"
pr "committer NAME is an agent, email Jordan's" nonzero "$(mk "ok" "$BASE" "$JN" "$JE" "hq-sealmark" "$JE")"
pr "author name is not Jordan Allen Lewis" nonzero "$(mk "ok" "$BASE" "Someone Else" "$JE" "$JN" "$JE")"
pr "committer name is not Jordan Allen Lewis" nonzero "$(mk "ok" "$BASE" "$JN" "$JE" "Someone Else" "$JE")"
pr "committer GitHub with a non-GitHub email" nonzero "$(mk "ok" "$BASE" "$JN" "$JE" "GitHub" "$JE")"

echo "== direct pushes and merged messages =="
H=$(mk "x"$'\n\n'"$CS: abc" "$BASE"); run "push: $CS trailer in the pushed commit" nonzero push "$BASE" "$H"
H=$(mk "Squash: Add thing (#9)"$'\n\n'"* wip"$'\n\n'"$AG: Hannah" "$BASE"); run "push: merged squash message with $AG trailer" nonzero push "$BASE" "$H"
H=$(mk "ok" "$BASE" "Claude" "$JE" "$JN" "$JE"); run "push: author name Claude" nonzero push "$BASE" "$H"
H=$(mk "ok" "$BASE" "$JN" "someone@example.com" "$JN" "someone@example.com"); run "push: foreign email" nonzero push "$BASE" "$H"
H1=$(mk "x"$'\n\n'"$CS: abc" "$BASE"); H2=$(mk "clean tip" "$H1"); run "push: bad commit in the middle of the range" nonzero push "$BASE" "$H2"
H=$(mk "x"$'\n\n'"$CS: abc" "$BASE"); run "push: zero before sha, bad head" nonzero push 0000000000000000000000000000000000000000 "$H"
run "push: empty before sha, bad head" nonzero push "" "$H"

echo "== fail closed =="
H=$(mk "x"$'\n\n'"$CS: abc" "$BASE")
run "unreachable base, bad commit (was rc=0 before)" nonzero pull_request deadbeefdeadbeefdeadbeefdeadbeefdeadbeef "$H"
run "unreachable base on push" nonzero push deadbeefdeadbeefdeadbeefdeadbeefdeadbeef "$H"
run "empty range (BASE == HEAD)" nonzero pull_request "$BASE" "$BASE"
run "empty base on a pull request" nonzero pull_request "" "$H"
run "missing head" nonzero pull_request "$BASE" ""
run "unknown head" nonzero pull_request "$BASE" deadbeefdeadbeefdeadbeefdeadbeefdeadbeef
run "unknown event" nonzero tag "$BASE" "$H"

echo
echo "attribution-guard self-test: $pass passed, $failn failed"
[ "$failn" = 0 ]
